#!/usr/bin/env node
/* Phase 10 — assemble the deployable site into mobile/www for Capacitor.
 *
 * The committed repo keeps the site sources at the repository root: that is
 * the same tree GitHub Pages serves (deploy-pages.yml uploads path '.').
 * mobile/www is a BUILD ARTIFACT — it is regenerated by `npm run app:sync`,
 * it is gitignored, and it must never be edited by hand.
 *
 * Everything the served site needs is copied (HTML/CSS/JS/data/assets);
 * everything that is not part of the served site is excluded: node_modules,
 * tests, test artifacts, .git/.github, the supabase/ backend sources, docs,
 * build scripts, the native android/ + ios/ projects, repo metadata files
 * and QA screenshots.
 */
import {cp, rm, stat, readdir} from 'node:fs/promises';
import {join, relative, sep} from 'node:path';
import {fileURLToPath} from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const OUT = join(ROOT, 'mobile', 'www');

const EXCLUDED_DIRS = new Set([
  '.git', '.github', 'node_modules', 'tests', 'test-results', 'artifacts',
  'supabase', 'docs', 'scripts', 'mobile', 'android', 'ios', 'infra',
  'render', 'functions', 'examples', 'skills', 'tools', 'integrations',
  'config',
]);
const EXCLUDED_FILES = new Set([
  'package.json', 'package-lock.json', 'playwright.config.js',
  'capacitor.config.json', '.gitignore',
]);
const EXCLUDED_FILE_PATTERNS = [/\.md$/i, /^e2e-.*\.png$/, /^qa-.*\.png$/];

function keep(absPath) {
  const rel = relative(ROOT, absPath);
  if (!rel) return true;
  const parts = rel.split(sep);
  if (parts.some((p) => EXCLUDED_DIRS.has(p))) return false;
  const base = parts[parts.length - 1];
  if (EXCLUDED_FILES.has(base)) return false;
  if (EXCLUDED_FILE_PATTERNS.some((re) => re.test(base))) return false;
  return true;
}

async function countAndSize(dir) {
  let files = 0, bytes = 0;
  for (const entry of await readdir(dir, {withFileTypes: true})) {
    const p = join(dir, entry.name);
    if (entry.isDirectory()) {
      const sub = await countAndSize(p);
      files += sub.files; bytes += sub.bytes;
    } else {
      files += 1;
      bytes += (await stat(p)).size;
    }
  }
  return {files, bytes};
}

await rm(OUT, {recursive: true, force: true});
// Copy entry by entry: fs.cp refuses to copy a directory into its own
// subdirectory (mobile/www lives inside the source tree).
for (const entry of await readdir(ROOT, {withFileTypes: true})) {
  const src = join(ROOT, entry.name);
  if (!keep(src)) continue;
  await cp(src, join(OUT, entry.name), {recursive: true, filter: (s) => keep(s)});
}

// The app must open and work with zero configuration: fail the build loudly
// if any entry the shell depends on is missing from the assembled www.
const REQUIRED = [
  'index.html', '404.html', 'sw.js', 'manifest.webmanifest',
  'supabase-config.js', 'studio.js', 'data/catalog.json',
  'assets/1up-anime-app-icon-512.png',
];
for (const rel of REQUIRED) {
  try {
    await stat(join(OUT, rel));
  } catch {
    throw new Error(`build-www: required site file missing from mobile/www: ${rel}`);
  }
}

const {files, bytes} = await countAndSize(OUT);
console.log(`build-www: mobile/www assembled — ${files} files, ${(bytes / 1048576).toFixed(2)} MiB`);
